// --- ui.FieldId.value.Print
// Convert value to a string. First, attempt conversion to a known string.
// If no string matches, print value as a numeric value.
void ui::value_Print(const ui::FieldId& parent, algo::cstring &lhs) {
    const char *strval = value_ToCstr(parent);
    if (strval) {
        lhs << strval;
    } else {
        lhs << parent.value;
    }
}

// --- ui.FieldId.value.SetStrptrMaybe
// Convert string to field.
// If the string is invalid, do not modify field and return false.
// In case of success, return true
bool ui::value_SetStrptrMaybe(ui::FieldId& parent, algo::strptr rhs) {
    bool ret = false;
    switch (elems_N(rhs)) {
        case 1: {
            switch (u64(rhs[0])) {
                case 'h': {
                    value_SetEnum(parent,ui_FieldId_h); ret = true; break;
                }
                case 'w': {
                    value_SetEnum(parent,ui_FieldId_w); ret = true; break;
                }
            }
            break;
        }
        case 2: {
            switch (u64(algo::ReadLE16(rhs.elems))) {
                case LE_STR2('b','g'): {
                    value_SetEnum(parent,ui_FieldId_bg); ret = true; break;
                }
                case LE_STR2('f','g'): {
                    value_SetEnum(parent,ui_FieldId_fg); ret = true; break;
                }
            }
            break;
        }
        case 3: {
            switch (u64(algo::ReadLE16(rhs.elems))|(u64(rhs[2])<<16)) {
                case LE_STR3('c','o','l'): {
                    value_SetEnum(parent,ui_FieldId_col); ret = true; break;
                }
                case LE_STR3('k','e','y'): {
                    value_SetEnum(parent,ui_FieldId_key); ret = true; break;
                }
                case LE_STR3('r','o','w'): {
                    value_SetEnum(parent,ui_FieldId_row); ret = true; break;
                }
            }
            break;
        }
        case 4: {
            switch (u64(algo::ReadLE32(rhs.elems))) {
                case LE_STR4('b','o','l','d'): {
                    value_SetEnum(parent,ui_FieldId_bold); ret = true; break;
                }
                case LE_STR4('c','o','l','s'): {
                    value_SetEnum(parent,ui_FieldId_cols); ret = true; break;
                }
                case LE_STR4('r','o','w','s'): {
                    value_SetEnum(parent,ui_FieldId_rows); ret = true; break;
                }
                case LE_STR4('t','e','x','t'): {
                    value_SetEnum(parent,ui_FieldId_text); ret = true; break;
                }
                case LE_STR4('t','y','p','e'): {
                    value_SetEnum(parent,ui_FieldId_type); ret = true; break;
                }
            }
            break;
        }
        case 5: {
            switch (u64(algo::ReadLE32(rhs.elems))|(u64(rhs[4])<<32)) {
                case LE_STR5('c','o','l','o','r'): {
                    value_SetEnum(parent,ui_FieldId_color); ret = true; break;
                }
                case LE_STR5('f','i','e','l','d'): {
                    value_SetEnum(parent,ui_FieldId_field); ret = true; break;
                }
                case LE_STR5('s','t','y','l','e'): {
                    value_SetEnum(parent,ui_FieldId_style); ret = true; break;
                }
                case LE_STR5('t','i','t','l','e'): {
                    value_SetEnum(parent,ui_FieldId_title); ret = true; break;
                }
                case LE_STR5('v','a','l','u','e'): {
                    value_SetEnum(parent,ui_FieldId_value); ret = true; break;
                }
            }
            break;
        }
        case 6: {
            switch (u64(algo::ReadLE32(rhs.elems))|(u64(algo::ReadLE16(rhs.elems+4))<<32)) {
                case LE_STR6('a','c','t','i','o','n'): {
                    value_SetEnum(parent,ui_FieldId_action); ret = true; break;
                }
                case LE_STR6('b','o','r','d','e','r'): {
                    value_SetEnum(parent,ui_FieldId_border); ret = true; break;
                }
                case LE_STR6('c','o','l','u','m','n'): {
                    value_SetEnum(parent,ui_FieldId_column); ret = true; break;
                }
                case LE_STR6('h','e','a','d','e','r'): {
                    value_SetEnum(parent,ui_FieldId_header); ret = true; break;
                }
                case LE_STR6('i','n','d','e','n','t'): {
                    value_SetEnum(parent,ui_FieldId_indent); ret = true; break;
                }
                case LE_STR6('l','a','y','o','u','t'): {
                    value_SetEnum(parent,ui_FieldId_layout); ret = true; break;
                }
                case LE_STR6('m','a','x','l','e','n'): {
                    value_SetEnum(parent,ui_FieldId_maxlen); ret = true; break;
                }
                case LE_STR6('w','i','d','g','e','t'): {
                    value_SetEnum(parent,ui_FieldId_widget); ret = true; break;
                }
                case LE_STR6('w','i','n','d','o','w'): {
                    value_SetEnum(parent,ui_FieldId_window); ret = true; break;
                }
                case LE_STR6('z','o','r','d','e','r'): {
                    value_SetEnum(parent,ui_FieldId_zorder); ret = true; break;
                }
            }
            break;
        }
        case 7: {
            switch (u64(algo::ReadLE32(rhs.elems))|(u64(algo::ReadLE16(rhs.elems+4))<<32)|(u64(rhs[6])<<48)) {
                case LE_STR7('b','i','n','d','i','n','g'): {
                    value_SetEnum(parent,ui_FieldId_binding); ret = true; break;
                }
                case LE_STR7('e','n','a','b','l','e','d'): {
                    value_SetEnum(parent,ui_FieldId_enabled); ret = true; break;
                }
                case LE_STR7('k','e','y','_','m','a','p'): {
                    value_SetEnum(parent,ui_FieldId_key_map); ret = true; break;
                }
                case LE_STR7('p','_','s','t','y','l','e'): {
                    value_SetEnum(parent,ui_FieldId_p_style); ret = true; break;
                }
                case LE_STR7('v','i','s','i','b','l','e'): {
                    value_SetEnum(parent,ui_FieldId_visible); ret = true; break;
                }
            }
            break;
        }
        case 8: {
            switch (algo::ReadLE64(rhs.elems)) {
                case LE_STR8('e','d','i','t','a','b','l','e'): {
                    value_SetEnum(parent,ui_FieldId_editable); ret = true; break;
                }
                case LE_STR8('p','_','p','a','r','e','n','t'): {
                    value_SetEnum(parent,ui_FieldId_p_parent); ret = true; break;
                }
                case LE_STR8('p','_','w','i','d','g','e','t'): {
                    value_SetEnum(parent,ui_FieldId_p_widget); ret = true; break;
                }
                case LE_STR8('p','_','w','i','n','d','o','w'): {
                    value_SetEnum(parent,ui_FieldId_p_window); ret = true; break;
                }
                case LE_STR8('s','o','r','t','a','b','l','e'): {
                    value_SetEnum(parent,ui_FieldId_sortable); ret = true; break;
                }
                case LE_STR8('t','r','e','e','_','c','f','g'): {
                    value_SetEnum(parent,ui_FieldId_tree_cfg); ret = true; break;
                }
            }
            break;
        }
        case 9: {
            switch (algo::ReadLE64(rhs.elems)) {
                case LE_STR8('f','o','c','u','s','a','b','l'): {
                    if (memcmp(rhs.elems+8,"e",1)==0) { value_SetEnum(parent,ui_FieldId_focusable); ret = true; break; }
                    break;
                }
                case LE_STR8('i','n','p','u','t','_','c','f'): {
                    if (memcmp(rhs.elems+8,"g",1)==0) { value_SetEnum(parent,ui_FieldId_input_cfg); ret = true; break; }
                    break;
                }
                case LE_STR8('s','e','l','e','c','t','i','o'): {
                    if (memcmp(rhs.elems+8,"n",1)==0) { value_SetEnum(parent,ui_FieldId_selection); ret = true; break; }
                    break;
                }
                case LE_STR8('t','a','b','l','e','_','c','f'): {
                    if (memcmp(rhs.elems+8,"g",1)==0) { value_SetEnum(parent,ui_FieldId_table_cfg); ret = true; break; }
                    break;
                }
                case LE_STR8('u','n','d','e','r','l','i','n'): {
                    if (memcmp(rhs.elems+8,"e",1)==0) { value_SetEnum(parent,ui_FieldId_underline); ret = true; break; }
                    break;
                }
            }
            break;
        }
        case 10: {
            switch (algo::ReadLE64(rhs.elems)) {
                case LE_STR8('s','e','l','e','c','t','a','b'): {
                    if (memcmp(rhs.elems+8,"le",2)==0) { value_SetEnum(parent,ui_FieldId_selectable); ret = true; break; }
                    break;
                }
                case LE_STR8('s','h','o','w','_','l','i','n'): {
                    if (memcmp(rhs.elems+8,"es",2)==0) { value_SetEnum(parent,ui_FieldId_show_lines); ret = true; break; }
                    break;
                }
            }
            break;
        }
        case 11: {
            switch (algo::ReadLE64(rhs.elems)) {
                case LE_STR8('a','c','t','i','o','n','_','t'): {
                    if (memcmp(rhs.elems+8,"ype",3)==0) { value_SetEnum(parent,ui_FieldId_action_type); ret = true; break; }
                    break;
                }
                case LE_STR8('c','h','i','l','d','_','f','i'): {
                    if (memcmp(rhs.elems+8,"eld",3)==0) { value_SetEnum(parent,ui_FieldId_child_field); ret = true; break; }
                    break;
                }
                case LE_STR8('l','a','y','o','u','t','_','t'): {
                    if (memcmp(rhs.elems+8,"ype",3)==0) { value_SetEnum(parent,ui_FieldId_layout_type); ret = true; break; }
                    break;
                }
                case LE_STR8('w','i','d','g','e','t','_','t'): {
                    if (memcmp(rhs.elems+8,"ype",3)==0) { value_SetEnum(parent,ui_FieldId_widget_type); ret = true; break; }
                    break;
                }
            }
            break;
        }
        case 12: {
            switch (algo::ReadLE64(rhs.elems)) {
                case LE_STR8('b','o','r','d','e','r','_','s'): {
                    if (memcmp(rhs.elems+8,"tyle",4)==0) { value_SetEnum(parent,ui_FieldId_border_style); ret = true; break; }
                    break;
                }
                case LE_STR8('s','o','u','r','c','e','_','c'): {
                    if (memcmp(rhs.elems+8,"type",4)==0) { value_SetEnum(parent,ui_FieldId_source_ctype); ret = true; break; }
                    break;
                }
                case LE_STR8('s','o','u','r','c','e','_','f'): {
                    if (memcmp(rhs.elems+8,"ield",4)==0) { value_SetEnum(parent,ui_FieldId_source_field); ret = true; break; }
                    break;
                }
            }
            break;
        }
        case 14: {
            switch (algo::ReadLE64(rhs.elems)) {
                case LE_STR8('s','e','l','e','c','t','i','o'): {
                    if (memcmp(rhs.elems+8,"n_mode",6)==0) { value_SetEnum(parent,ui_FieldId_selection_mode); ret = true; break; }
                    break;
                }
            }
            break;
        }
    }
    return ret;
}

// --- ui.FieldId.value.SetStrptr
// Convert string to field.
// If the string is invalid, set numeric value to DFLT
void ui::value_SetStrptr(ui::FieldId& parent, algo::strptr rhs, ui_FieldIdEnum dflt) {
    if (!value_SetStrptrMaybe(parent,rhs)) value_SetEnum(parent,dflt);
}

// --- ui.FieldId.value.ReadStrptrMaybe
// Convert string to field. Return success value
bool ui::value_ReadStrptrMaybe(ui::FieldId& parent, algo::strptr rhs) {
    bool retval = false;
    retval = value_SetStrptrMaybe(parent,rhs); // try symbol conversion
    if (!retval) { // didn't work? try reading as underlying type
        retval = i32_ReadStrptrMaybe(parent.value,rhs);
    }
    return retval;
}

// --- ui.FieldId..ReadStrptrMaybe
