// --- ui.InputCfg..ReadFieldMaybe
bool ui::InputCfg_ReadFieldMaybe(ui::InputCfg& parent, algo::strptr field, algo::strptr strval) {
    bool retval = true;
    ui::FieldId field_id;
    (void)value_SetStrptrMaybe(field_id,field);
    switch(field_id) {
        case ui_FieldId_input_cfg: {
            retval = algo::Smallstr50_ReadStrptrMaybe(parent.input_cfg, strval);
        } break;
        case ui_FieldId_p_widget: {
            retval = algo::Smallstr50_ReadStrptrMaybe(parent.p_widget, strval);
        } break;
        case ui_FieldId_editable: {
            retval = bool_ReadStrptrMaybe(parent.editable, strval);
        } break;
        case ui_FieldId_maxlen: {
            retval = i32_ReadStrptrMaybe(parent.maxlen, strval);
        } break;
        default: {
            retval = false;
            algo_lib::AppendErrtext("comment", "unrecognized attr");
        } break;
    }
    if (!retval) {
        algo_lib::AppendErrtext("attr",field);
    }
    return retval;
}

